import assert from 'node:assert/strict';
import fs from 'node:fs';
import { z } from 'zod';
import { toolArgSchemas } from '../dist/tools/schemas.js';
import { toToolInputSchema } from '../dist/tools/json-schema.js';
import {
  buildUnsupportedParamsWarning,
  detectUnsupportedParams,
  getSupportedParams,
} from '../dist/utils/unsupportedParams.js';
import { runIfMain } from './helpers/run-if-main.js';

// Captured from the official 0.3.1 package before the dependency migration.
// This is a compatibility oracle, not output generated by the new converter.
const baseline = JSON.parse(fs.readFileSync(new URL('./fixtures/tool-input-schemas-v031.json', import.meta.url), 'utf8'));

export default async function runTests() {
  assert.equal(baseline.baseline.sourceCommit, '7251da501d760e6eb5f95d802d9b42c741190950');
  assert.deepEqual(Object.keys(toolArgSchemas).sort(), Object.keys(baseline.tools).sort());
  for (const [name, schema] of Object.entries(toolArgSchemas)) {
    assert.deepEqual(toToolInputSchema(schema), baseline.tools[name], `${name}: published input contract changed`);
    assert.deepEqual(getSupportedParams(schema), Object.keys(baseline.tools[name].properties), `${name}: supported parameter names`);
    assert.deepEqual(detectUnsupportedParams({ unsupported: 'value' }, schema), ['unsupported'], `${name}: unsupported parameter warning`);
  }

  for (const sample of baseline.validation) {
    const parsed = toolArgSchemas[sample.tool].safeParse(sample.input);
    const label = `${sample.tool}: ${sample.label}`;
    assert.equal(parsed.success, sample.success, `${label}: acceptance changed`);
    if (parsed.success) assert.deepEqual(parsed.data, sample.data, `${label}: defaults or parsed arguments changed`);
  }

  // Record contents stay free-form where promised, without hiding unsupported
  // top-level fields or dropping warnings on refined/optional/pipeline objects.
  assert.deepEqual(detectUnsupportedParams({ path: 'sample', options: { custom: true } }, toolArgSchemas.read_file), []);
  const object = z.object({ supported: z.string() });
  for (const schema of [
    object.refine(value => value.supported.length > 0),
    object.optional().nullable().default({ supported: 'fallback' }),
    object.transform(value => value.supported),
    z.preprocess(value => value, object),
  ]) {
    assert.deepEqual(getSupportedParams(schema), ['supported']);
    assert.deepEqual(detectUnsupportedParams({ supported: 'yes', invented: true }, schema), ['invented']);
  }
  for (const schema of [z.string(), z.array(z.string()), z.record(z.string(), z.any()), null, {}]) {
    assert.deepEqual(getSupportedParams(schema), []);
    assert.deepEqual(detectUnsupportedParams({ invented: true }, schema), []);
  }
  for (const input of [null, [], 'text', 1]) {
    assert.deepEqual(detectUnsupportedParams(input, object), []);
  }
  assert.equal(buildUnsupportedParamsWarning('read_file', ['view_range'], ['path']),
    'You sent parameters not supported by this tool, which were ignored: view_range. Supported parameters for read_file: path.');

  // Do not hide unsupported future schema types behind an unrestricted schema,
  // or widen a typed catchall while retaining the existing passthrough behavior.
  assert.throws(() => toToolInputSchema(z.object({ unsupported: z.bigint() })));
  assert.throws(() => toToolInputSchema(z.string()), /must be an object/);
  assert.deepEqual(toToolInputSchema(z.object({}).catchall(z.string())).additionalProperties, { type: 'string' });

  const first = toolArgSchemas.track_ui_event.parse({ event: 'first' });
  first.params.changed = true;
  assert.deepEqual(toolArgSchemas.track_ui_event.parse({ event: 'second' }).params, {}, 'default records must not be shared between calls');

  console.log(`Passed: ${Object.keys(baseline.tools).length} exact tool input schemas, ${baseline.validation.length} baseline validation cases, and unsupported-parameter/default isolation regressions.`);
}

runIfMain(import.meta.url, runTests);
